dashboard.definition:
{
  "title": "Multi-Cluster Groups",
  "description": "Maps+ clusterGroup: seven cluster groups keep different offence types from clustering together.",
  "dataSources": {
    "ds_map": {
      "type": "ds.search",
      "options": {
        "query": "| inputlookup chicago-crime.csv \n| eval markerColor=case(like(description, \"%SIMPLE%\"), \"red\", like(description, \"%DOMESTIC BATTERY%\"), \"yellow\", like(description, \"%500 AND UNDER%\"), \"green\", like(description, \"%TO PROPERTY%\"), \"orange\", like(description, \"%RETAIL THEFT%\"), \"darkred\", like(description, \"%TO VEHICLE%\"), \"cadetblue\", 1=1, \"blue\"),\nicon=case(like(description, \"%SIMPLE%\"), \"exclamation-triangle\", like(description, \"%DOMESTIC BATTERY%\"), \"battery-2\", like(description, \"%500 AND UNDER%\"), \"gavel\", like(description, \"%TO PROPERTY%\"), \"building\", like(description, \"%RETAIL THEFT%\"), \"shopping-cart\", like(description, \"%TO VEHICLE%\"), \"car\", 1=1, \"hand-lizard-o\"),\nclusterGroup=case(like(description, \"%SIMPLE%\"), \"simple\", like(description, \"%DOMESTIC BATTERY%\"), \"battery\", like(description, \"%500 AND UNDER%\"), \"under_five_hundred\", like(description, \"%TO PROPERTY%\"), \"property\", like(description, \"%RETAIL THEFT%\"), \"theft\", like(description, \"%TO VEHICLE%\"), \"vehicle\", 1=1, \"default\")\n| eval description = \"<b>\".description.\"</b>\", tooltip=description\n| table latitude, longitude, description, tooltip, markerColor, icon, clusterGroup",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      },
      "name": "Chicago crime cluster groups"
    }
  },
  "visualizations": {
    "md_intro": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "The default behavior is to cluster all markers into the same cluster group. Use the `clusterGroup` field for granular control over cluster grouping. The following example creates seven cluster groups.\n"
      }
    },
    "viz_map": {
      "type": "leaflet_maps_app.maps-plus",
      "dataSources": {
        "primary": "ds_map"
      },
      "options": {
        "leaflet_maps_app.maps-plus.allPopups": "0",
        "leaflet_maps_app.maps-plus.animate": "1",
        "leaflet_maps_app.maps-plus.autoFitAndZoom": "1",
        "leaflet_maps_app.maps-plus.autoFitAndZoomDelay": "500",
        "leaflet_maps_app.maps-plus.bingMaps": "0",
        "leaflet_maps_app.maps-plus.bingMapsLabelLanguage": "en-US",
        "leaflet_maps_app.maps-plus.bingMapsTileLayer": "CanvasLight",
        "leaflet_maps_app.maps-plus.cluster": "1",
        "leaflet_maps_app.maps-plus.contextMenu": "1",
        "leaflet_maps_app.maps-plus.criticalThreshold": "80",
        "leaflet_maps_app.maps-plus.defaultHeight": "600",
        "leaflet_maps_app.maps-plus.disableClusteringAtZoom": "0",
        "leaflet_maps_app.maps-plus.drilldown": "0",
        "leaflet_maps_app.maps-plus.drilldownAction": "dblclick",
        "leaflet_maps_app.maps-plus.fullScreen": "0",
        "leaflet_maps_app.maps-plus.googlePlacesPosition": "topleft",
        "leaflet_maps_app.maps-plus.googlePlacesSearch": "0",
        "leaflet_maps_app.maps-plus.googlePlacesZoomLevel": "12",
        "leaflet_maps_app.maps-plus.heatmapBlur": "15",
        "leaflet_maps_app.maps-plus.heatmapColorGradient": "{\"0.4\":\"blue\",\"0.6\":\"cyan\",\"0.7\":\"lime\",\"0.8\":\"yellow\",\"1\":\"red\"}",
        "leaflet_maps_app.maps-plus.heatmapEnable": "0",
        "leaflet_maps_app.maps-plus.heatmapMaxPointIntensity": "1.0",
        "leaflet_maps_app.maps-plus.heatmapMinOpacity": "1.0",
        "leaflet_maps_app.maps-plus.heatmapOnly": "0",
        "leaflet_maps_app.maps-plus.heatmapRadius": "25",
        "leaflet_maps_app.maps-plus.i18nLanguage": "en",
        "leaflet_maps_app.maps-plus.layerControl": "1",
        "leaflet_maps_app.maps-plus.layerControlCollapsed": "1",
        "leaflet_maps_app.maps-plus.mapCenterLat": "39.50",
        "leaflet_maps_app.maps-plus.mapCenterLon": "-98.35",
        "leaflet_maps_app.maps-plus.mapCenterZoom": "6",
        "leaflet_maps_app.maps-plus.mapTile": "http://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
        "leaflet_maps_app.maps-plus.maxClusterRadius": "80",
        "leaflet_maps_app.maps-plus.maxSpiderfySize": "100",
        "leaflet_maps_app.maps-plus.maxZoom": "19",
        "leaflet_maps_app.maps-plus.measureActiveColor": "#00ff00",
        "leaflet_maps_app.maps-plus.measureCompletedColor": "#0066ff",
        "leaflet_maps_app.maps-plus.measureIconPosition": "topright",
        "leaflet_maps_app.maps-plus.measureLocalization": "en",
        "leaflet_maps_app.maps-plus.measurePrimaryAreaUnit": "acres",
        "leaflet_maps_app.maps-plus.measurePrimaryLengthUnit": "feet",
        "leaflet_maps_app.maps-plus.measureSecondaryAreaUnit": "sqmiles",
        "leaflet_maps_app.maps-plus.measureSecondaryLengthUnit": "miles",
        "leaflet_maps_app.maps-plus.measureTool": "1",
        "leaflet_maps_app.maps-plus.minZoom": "1",
        "leaflet_maps_app.maps-plus.multiplePopups": "0",
        "leaflet_maps_app.maps-plus.pathColorList": "#0003F0,#D43C29,darkgreen,0xe2d400,darkred,#23A378",
        "leaflet_maps_app.maps-plus.pathRenderer": "svg",
        "leaflet_maps_app.maps-plus.pathSplitInterval": "60",
        "leaflet_maps_app.maps-plus.pathSplits": "0",
        "leaflet_maps_app.maps-plus.permanentTooltip": "0",
        "leaflet_maps_app.maps-plus.rangeOneBgColor": "#B5E28C",
        "leaflet_maps_app.maps-plus.rangeOneFgColor": "#6ECC39",
        "leaflet_maps_app.maps-plus.rangeThreeBgColor": "#FD9C73",
        "leaflet_maps_app.maps-plus.rangeThreeFgColor": "#F18017",
        "leaflet_maps_app.maps-plus.rangeTwoBgColor": "#F1D357",
        "leaflet_maps_app.maps-plus.rangeTwoFgColor": "#F0C20C",
        "leaflet_maps_app.maps-plus.refreshInterval": "0",
        "leaflet_maps_app.maps-plus.renderer": "svg",
        "leaflet_maps_app.maps-plus.scrollWheelZoom": "1",
        "leaflet_maps_app.maps-plus.showPathLines": "0",
        "leaflet_maps_app.maps-plus.showProgress": "1",
        "leaflet_maps_app.maps-plus.singleMarkerMode": "0",
        "leaflet_maps_app.maps-plus.spiderfyDistanceMultiplier": "1",
        "leaflet_maps_app.maps-plus.stickyTooltip": "1",
        "leaflet_maps_app.maps-plus.warningThreshold": "55"
      }
    },
    "md_map": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### What this shows\n\nChicago crime markers split into seven cluster groups by offence type. Markers in different groups never merge into the same bubble, so each offence type clusters on its own.\n\n### The SPL\n\n```spl\n| inputlookup chicago-crime.csv \n| eval markerColor=case(like(description, \"%SIMPLE%\"), \"red\", like(description, \"%DOMESTIC BATTERY%\"), \"yellow\", like(description, \"%500 AND UNDER%\"), \"green\", like(description, \"%TO PROPERTY%\"), \"orange\", like(description, \"%RETAIL THEFT%\"), \"darkred\", like(description, \"%TO VEHICLE%\"), \"cadetblue\", 1=1, \"blue\"),\nicon=case( ... ),\nclusterGroup=case(like(description, \"%SIMPLE%\"), \"simple\", like(description, \"%DOMESTIC BATTERY%\"), \"battery\", like(description, \"%500 AND UNDER%\"), \"under_five_hundred\", like(description, \"%TO PROPERTY%\"), \"property\", like(description, \"%RETAIL THEFT%\"), \"theft\", like(description, \"%TO VEHICLE%\"), \"vehicle\", 1=1, \"default\")\n| eval description = \"<b>\".description.\"</b>\", tooltip=description\n| table latitude, longitude, description, tooltip, markerColor, icon, clusterGroup\n```\n\n### How it works\n\n1. `inputlookup` returns `latitude`, `longitude` and `description` per incident.\n2. `markerColor` and `icon` come from `case(like(description, ...))`, one branch per offence type and a `1=1` catch-all.\n3. `clusterGroup` uses the same `case()` ladder and returns a group name: `simple`, `battery`, `under_five_hundred`, `property`, `theft`, `vehicle`, and `default` for everything else.\n4. Maps+ builds one cluster layer per distinct `clusterGroup` value, so zooming out merges markers only within their own group.\n5. `description` is wrapped in HTML bold and copied to `tooltip`; `table` keeps the Maps+ fields.\n\n### Field formats and rules\n\n| Field | Format | Rule / gotcha |\n|---|---|---|\n| `latitude`, `longitude` | decimal degrees | Exact lowercase names; required. |\n| `clusterGroup` | any string, default `default` | Different values never cluster together. Avoid `one`, `two` and `three`: they clash with Maps+ CSS classes. |\n| `markerColor` | png: named color | Must be one of Maps+'s fixed names or the marker is blank. `yellow` (used for domestic battery here) is not in the list. |\n| `icon` | glyph name without prefix | `gavel`, not `fa-gavel`. |\n| `description`, `tooltip` | HTML | Click popup and hover text; escape event text. |\n\n### Try it\n\n- In Open in Search, change the `\"yellow\"` for `%DOMESTIC BATTERY%` to `\"beige\"` to get a visible pin color.\n- Replace the last branch of `clusterGroup` (`1=1, \"default\"`) with `1=1, \"other\"` and zoom out to see the group split.\n"
      }
    }
  },
  "layout": {
    "globalInputs": [],
    "tabs": {
      "items": [
        {
          "label": "New tab",
          "layoutId": "layout_1"
        }
      ]
    },
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1440,
          "height": 1220,
          "display": "auto",
          "backgroundColor": "#FFFFFF"
        },
        "structure": [
          {
            "item": "md_intro",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 1440,
              "h": 110
            }
          },
          {
            "item": "viz_map",
            "type": "block",
            "position": {
              "x": 0,
              "y": 110,
              "w": 720,
              "h": 760
            }
          },
          {
            "item": "md_map",
            "type": "block",
            "position": {
              "x": 720,
              "y": 110,
              "w": 720,
              "h": 1110
            }
          }
        ]
      }
    }
  }
}
